create table la_resources
(
    ID              varchar(64)   not null
        primary key,
    PARENT_ID       varchar(64)   null,
    RES_NAME        varchar(128)  null comment '资源名称',
    RES_PATH        varchar(200)  null comment '访问路径',
    RES_LEVEL       int           null comment '资源级别',
    RES_TYPE        int           null comment '资源类型',
    RES_URL         varchar(510)  null,
    RES_MODE        int default 0 null comment '资源模式 0:后台资源,1:APP资源',
    METHOD          varchar(255)  null comment '对应后台方法函数',
    ICON            varchar(128)  null,
    HIDDEN          int default 0 not null comment '是否隐藏',
    PARENT_KEYS     varchar(1000) null comment '上级节点集',
    IS_DEV          int default 0 not null comment '是否是开发者功能, 0:否,1:是',
    REMARK          varchar(2000) null,
    URL             varchar(255)  null comment '资源路径',
    KEY_NAME        varchar(64)   null comment '国际化KEY',
    KEEP_ALIVE      int default 0 null comment '是否缓存',
    EXPAND          varchar(1024) null comment '扩展字段',
    BUSINESS_EXPAND varchar(1024) null comment '业务扩展字段',
    ORDER_NO        int           not null comment '排序'
)
    comment '资源信息表';

